import sqlite3

from payments import gateway, service


def _idempotency_key(headers):
    for name, value in (headers or {}).items():
        if name.lower() == "idempotency-key":
            return value
    return None


def _replay(conn, key, customer_id, cents):
    """Return the response for an earlier request with this key, or None if there was none."""
    row = conn.execute("SELECT id, customer_id, cents, charge_id FROM payments WHERE idempotency_key = ?",
                       (key,)).fetchone()
    if row is None:
        return None
    if row["customer_id"] != customer_id or row["cents"] != cents:
        return 409, {"error": "idempotency key reused"}
    return 201, {"id": row["id"], "customer_id": row["customer_id"], "cents": row["cents"],
                 "charge_id": row["charge_id"]}


def handle_post(conn, request):
    """POST /payments. The body is {"customer_id": int, "cents": int}; an Idempotency-Key header is optional."""
    body = request.get("body") or {}
    customer_id, cents = body.get("customer_id"), body.get("cents")
    if type(customer_id) is not int or type(cents) is not int or cents <= 0:
        return 400, {"error": "customer_id and a positive cents are required"}
    key = _idempotency_key(request.get("headers"))
    if key is not None:
        earlier = _replay(conn, key, customer_id, cents)
        if earlier is not None:
            return earlier
    try:
        payment = service.create_payment(conn, customer_id, cents, idempotency_key=key)
    except service.UnknownCustomer:
        return 404, {"error": "no such customer"}
    except gateway.Declined as e:
        conn.rollback()
        return 402, {"error": f"declined: {e}"}
    except sqlite3.IntegrityError:
        # A concurrent request with the same key committed first; undo our charge and replay theirs.
        conn.rollback()
        if key is not None:
            earlier = _replay(conn, key, customer_id, cents)
            if earlier is not None:
                return earlier
        raise
    return 201, payment

