import sqlite3

from payments import gateway


class UnknownCustomer(Exception):
    pass


class KeyConflict(Exception):
    """An idempotency key was reused with a different customer or amount."""


def create_payment(conn, customer_id, cents, idempotency_key=None):
    """Charge the customer and record the payment; return it as a dict.

    With idempotency_key, a payment already recorded under that key is returned
    without charging again. A key reused with another customer or amount raises KeyConflict.
    """
    if idempotency_key is None:
        payment = _charge_and_insert(conn, customer_id, cents, None)
        conn.commit()
        return payment
    if conn.in_transaction:
        conn.commit()
    conn.execute("BEGIN IMMEDIATE")
    try:
        payment = _replay_or_charge(conn, customer_id, cents, idempotency_key)
        conn.commit()
    except BaseException:
        conn.rollback()
        raise
    return payment


def _replay_or_charge(conn, customer_id, cents, idempotency_key):
    found = _find_by_key(conn, idempotency_key)
    if found is None:
        try:
            return _charge_and_insert(conn, customer_id, cents, idempotency_key)
        except sqlite3.IntegrityError:
            # The key was stored by someone else after our lookup: roll back our charge and replay theirs.
            conn.rollback()
            found = _find_by_key(conn, idempotency_key)
            if found is None:
                raise
    if (found["customer_id"], found["cents"]) != (customer_id, cents):
        raise KeyConflict(idempotency_key)
    return found


def _find_by_key(conn, idempotency_key):
    row = conn.execute("SELECT id, customer_id, cents, charge_id FROM payments WHERE idempotency_key = ?",
                       (idempotency_key,)).fetchone()
    if row is None:
        return None
    return {"id": row[0], "customer_id": row[1], "cents": row[2], "charge_id": row[3]}


def _charge_and_insert(conn, customer_id, cents, idempotency_key):
    """Charge and insert without committing; the caller decides the transaction boundary."""
    if conn.execute("SELECT 1 FROM customers WHERE id = ?", (customer_id,)).fetchone() is None:
        raise UnknownCustomer(customer_id)
    charge_id = gateway.charge(conn, cents)
    cur = conn.execute("INSERT INTO payments (customer_id, cents, charge_id, idempotency_key) VALUES (?, ?, ?, ?)",
                       (customer_id, cents, charge_id, idempotency_key))
    return {"id": cur.lastrowid, "customer_id": customer_id, "cents": cents, "charge_id": charge_id}

