import sqlite3

from payments import gateway


class UnknownCustomer(Exception):
    pass


class IdempotencyConflict(Exception):
    """The idempotency key was already used for a different customer or amount."""


def find_by_key(conn, key):
    """Return the payment stored under this idempotency key as a dict, or None."""
    row = conn.execute(
        "SELECT id, customer_id, cents, charge_id FROM payments WHERE idempotency_key = ?", (key,)
    ).fetchone()
    return None if row is None else dict(row)


def _charge_and_record(conn, customer_id, cents, key):
    """Charge and insert the payment. The caller owns the transaction."""
    if conn.execute("SELECT 1 FROM customers WHERE id = ?", (customer_id,)).fetchone() is None:
        raise UnknownCustomer(customer_id)
    charge_id = gateway.charge(conn, cents)
    cur = conn.execute("INSERT INTO payments (customer_id, cents, charge_id, idempotency_key) VALUES (?, ?, ?, ?)",
                       (customer_id, cents, charge_id, key))
    return {"id": cur.lastrowid, "customer_id": customer_id, "cents": cents, "charge_id": charge_id}


def _replay(existing, customer_id, cents):
    """A repeat of a stored request gets the stored payment; a different request under the same key is refused."""
    if (existing["customer_id"], existing["cents"]) != (customer_id, cents):
        raise IdempotencyConflict(existing["id"])
    return existing


def _create_keyed(conn, customer_id, cents, key):
    # BEGIN IMMEDIATE takes the write lock before the lookup, so two workers cannot both miss and both charge.
    conn.execute("BEGIN IMMEDIATE")
    try:
        existing = find_by_key(conn, key)
        if existing is None:
            payment = _charge_and_record(conn, customer_id, cents, key)
            conn.commit()
            return payment
    except BaseException:
        conn.rollback()
        raise
    conn.rollback()  # a repeat writes nothing, so release the lock
    return _replay(existing, customer_id, cents)


def create_payment(conn, customer_id, cents, idempotency_key=None):
    """Charge the customer and record the payment; return it as a dict.

    With an idempotency_key, a key already stored for the same customer and cents returns the stored
    payment without charging again. A key stored for anything else raises IdempotencyConflict.
    """
    if idempotency_key is None:
        payment = _charge_and_record(conn, customer_id, cents, None)
        conn.commit()
        return payment
    try:
        return _create_keyed(conn, customer_id, cents, idempotency_key)
    except sqlite3.IntegrityError:
        # Backstop for a key stored by a writer the lock did not cover. The rollback also undoes the charge row.
        conn.rollback()
        existing = find_by_key(conn, idempotency_key)
        if existing is None:
            raise
        return _replay(existing, customer_id, cents)

