import sqlite3

from payments import gateway, service


def handle_post(conn, request):
    """POST /payments. The body is {"customer_id": int, "cents": int}.

    With an Idempotency-Key header the request is replayable: see _create_with_key.
    """
    body = request.get("body") or {}
    customer_id, cents = body.get("customer_id"), body.get("cents")
    if type(customer_id) is not int or type(cents) is not int or cents <= 0:
        return 400, {"error": "customer_id and a positive cents are required"}
    key = _header(request.get("headers"), "idempotency-key")
    if key is None:
        return _create(conn, customer_id, cents, None)
    if not key.strip():
        return 400, {"error": "Idempotency-Key must not be empty"}
    return _create_with_key(conn, customer_id, cents, key)


def _header(headers, name):
    """Return the value of the named header, matching the name case-insensitively, or None."""
    for field, value in (headers or {}).items():
        if field.lower() == name:
            return value
    return None


def _create(conn, customer_id, cents, key):
    try:
        payment = service.create_payment(conn, customer_id, cents, key)
    except service.UnknownCustomer:
        return 404, {"error": "no such customer"}
    except gateway.Declined as e:
        conn.rollback()
        return 402, {"error": f"declined: {e}"}
    return 201, payment


def _create_with_key(conn, customer_id, cents, key):
    # BEGIN IMMEDIATE takes the write lock before the lookup, so concurrent retries
    # of one key run one at a time and the later ones see the committed payment.
    conn.execute("BEGIN IMMEDIATE")
    try:
        stored = _find(conn, key)
        if stored is None:
            try:
                return _create(conn, customer_id, cents, key)  # commits when it returns 201
            except sqlite3.IntegrityError:
                # The unique index on the key rejected our insert, so another request
                # stored this key first. Undo our attempt, then replay what it stored.
                conn.rollback()
                stored = _find(conn, key)
                if stored is None:
                    raise
        return _replay(stored, customer_id, cents)
    finally:
        if conn.in_transaction:
            conn.rollback()


def _find(conn, key):
    return conn.execute(
        "SELECT id, customer_id, cents, charge_id FROM payments WHERE idempotency_key = ?",
        (key,)).fetchone()


def _replay(stored, customer_id, cents):
    # Only successful payments are stored with a key, so the earlier response was a 201.
    if stored["customer_id"] == customer_id and stored["cents"] == cents:
        return 201, {"id": stored["id"], "customer_id": stored["customer_id"],
                     "cents": stored["cents"], "charge_id": stored["charge_id"]}
    return 409, {"error": "idempotency key reused"}

