import sqlite3

from payments import gateway


class UnknownCustomer(Exception):
    pass


class KeyReused(Exception):
    """The idempotency key belongs to an earlier payment with a different customer or amount."""


def _as_dict(row):
    return {"id": row["id"], "customer_id": row["customer_id"], "cents": row["cents"],
            "charge_id": row["charge_id"]}


def _earlier_payment(conn, customer_id, cents, idempotency_key):
    """Return the stored payment for this key, None if there is none; raise KeyReused on a mismatch."""
    row = conn.execute("SELECT id, customer_id, cents, charge_id FROM payments WHERE idempotency_key = ?",
                       (idempotency_key,)).fetchone()
    if row is None:
        return None
    if (row["customer_id"], row["cents"]) != (customer_id, cents):
        raise KeyReused(idempotency_key)
    return _as_dict(row)


def create_payment(conn, customer_id, cents, idempotency_key=None):
    """Charge the customer and record the payment; return it as a dict.

    With an idempotency_key, a payment already stored under that key is returned instead of
    charging again (KeyReused if its customer or amount differ).
    """
    if idempotency_key is None:
        return _charge_and_insert(conn, customer_id, cents, None)
    # Take the write lock before the lookup so lookup, charge and insert are serialized
    # across all workers: a concurrent retry waits here and then finds the stored row.
    if conn.in_transaction:
        conn.commit()
    conn.execute("BEGIN IMMEDIATE")
    try:
        earlier = _earlier_payment(conn, customer_id, cents, idempotency_key)
        if earlier is not None:
            conn.rollback()
            return earlier
        return _charge_and_insert(conn, customer_id, cents, idempotency_key)
    except sqlite3.IntegrityError:
        # Another writer stored the key first (should not happen under the lock, but the
        # unique index is the final guard). Our insert is discarded; answer from the stored row.
        conn.rollback()
        earlier = _earlier_payment(conn, customer_id, cents, idempotency_key)
        if earlier is None:
            raise
        return earlier
    except BaseException:
        conn.rollback()
        raise


def _charge_and_insert(conn, customer_id, cents, idempotency_key):
    if conn.execute("SELECT 1 FROM customers WHERE id = ?", (customer_id,)).fetchone() is None:
        raise UnknownCustomer(customer_id)
    charge_id = gateway.charge(conn, cents)
    cur = conn.execute("INSERT INTO payments (customer_id, cents, charge_id, idempotency_key) VALUES (?, ?, ?, ?)",
                       (customer_id, cents, charge_id, idempotency_key))
    conn.commit()
    return {"id": cur.lastrowid, "customer_id": customer_id, "cents": cents, "charge_id": charge_id}
